import sys
import xml.etree.ElementTree as ET
from collections import defaultdict

def parse_config(xml_path):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        if root.tag != 'services':
            print("CONFIG_ERROR invalid_config", file=sys.stderr)
            sys.exit(2)
    except (IOError, ET.ParseError):
        print("CONFIG_ERROR invalid_config", file=sys.stderr)
        sys.exit(2)

    services = {}
    for service_elem in root.findall('service'):
        name = service_elem.get('name')
        if not name:
            print("CONFIG_ERROR invalid_config", file=sys.stderr)
            sys.exit(2)

        token_elem = service_elem.find('token')
        if not token_elem or not token_elem.text.strip():
            print("CONFIG_ERROR invalid_config", file=sys.stderr)
            sys.exit(2)

        token = token_elem.text.strip()
        roles = set()
        for role_elem in service_elem.findall('role'):
            role = role_elem.text.strip()
            if role:
                roles.add(role)

        services[name] = (token, roles)

    return services

def process_requests(services):
    line_num = 1
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        parts = line.split('|', 3)
        if len(parts) < 4:
            print("DENY -", end='\n')
            print(f"ERROR malformed line={line_num}", file=sys.stderr)
            continue

        service, token, role, payload = parts
        if not service or not token or not role:
            print("DENY -", end='\n')
            print(f"ERROR malformed line={line_num}", file=sys.stderr)
            continue

        if service not in services:
            print(f"DENY {service}", end='\n')
            print(f"WARN unknown_service service={service}", file=sys.stderr)
        elif token != services[service][0]:
            print(f"DENY {service}", end='\n')
            print(f"WARN bad_token service={service} role={role}", file=sys.stderr)
        elif role not in services[service][1]:
            print(f"DENY {service}", end='\n')
            print(f"WARN role_denied service={service} role={role}", file=sys.stderr)
        else:
            print(f"ALLOW {service} {payload}", end='\n')

        line_num += 1

def main():
    if len(sys.argv) != 2:
        print("Usage: python access_runner.py <config_file>", file=sys.stderr)
        sys.exit(1)

    services = parse_config(sys.argv[1])
    process_requests(services)

if __name__ == "__main__":
    main()

